def lca(raiz: "Nodo | None", p: int, q: int) -> "Nodo | None":
    """Least Common Ancestor en BST."""
    if raiz is None:
        return None
    if p < raiz.val and q < raiz.val:
        return lca(raiz.izq, p, q)
    if p > raiz.val and q > raiz.val:
        return lca(raiz.der, p, q)
    return raiz

