    protected Trie createTrie() {
        return new Trie();
    }

    public static void main(String[] args) {
        Main main = new Main();
        Trie trie = main.createTrie();
        trie.insert("apple");
        boolean searchResult = trie.search("apple"); // returns true
        boolean startsWithResult = trie.startsWith("app"); // returns true
        System.out.println("Search Result: " + searchResult);
        System.out.println("Starts With Result: " + startsWithResult);
    }
}
```

