class Node {
    value: string;
    depth: number;
    width: number;
    left: Node | null;
    right: Node | null;

    constructor(value: string) {
        this.value = value;
        this.depth = 0;
        this.width = 0;
        this.left = null;
        this.right = null;
    }

    getNodesAtDepth(depth: number): Array<Node> {
        if (this.depth == depth) {
            return [this];
        }
        if (this.depth < depth) {
            const leftNodes = this.left ? this.left.getNodesAtDepth(depth) : [new Node("")];
            const rightNodes = this.right ? this.right.getNodesAtDepth(depth) : [new Node("")];
            return [...leftNodes, ...rightNodes];
        }
        return [];
    }
}
