### Problem:
You are tasked with implementing a custom data structure in C# to represent a binary search tree (BST) and performing various operations on it. A binary search tree is a binary tree where for each node, all elements in its left subtree are less than the node, and all elements in its right subtree are greater than the node.

Your task is to implement the following operations for the binary search tree:
1. Insertion of a new node with a given value.
2. Deletion of a node with a given value.
3. Searching for a node with a given value.
4. Traversal of the tree in in-order, pre-order, and post-order.

You should implement the BSTNode class to represent a node in the binary search tree, and the BinarySearchTree class to manage the tree and perform the operations.

Your implementation should include the following classes and methods:
- `BSTNode` class with properties for value, left child, and right child.
- `BinarySearchTree` class with methods for insertion, deletion, searching, and traversal.

You should also implement the traversal methods to return the elements in the specified order.

Your task is to write the C# implementation for the `BSTNode` and `BinarySearchTree` classes to fulfill the requirements.

### Solution:
```csharp
public class BSTNode
{
    public int Value { get; set; }
    public BSTNode Left { get; set; }
    public BSTNode Right { get; set; }

    public BSTNode(int value)
    {
        Value = value;
        Left = null;
        Right = null;
    }
}

public class BinarySearchTree
{
    private BSTNode root;

    public BinarySearchTree()
    {
        root = null;
    }

    public void Insert(int value)
    {
        root = InsertRec(root, value);
    }

    private BSTNode InsertRec(BSTNode root, int value)
    {
        if (root == null)
        {
            root = new BSTNode(value);
            return root;
        }

        if (value < root.Value)
        {
            root.Left = InsertRec(root.Left, value);
        }
        else if (value > root.Value)
        {
            root.Right = InsertRec(root.Right, value);
        }

        return root;
    }

    public void Delete(int value)
    {
        root = DeleteRec(root, value);
    }

    private BSTNode DeleteRec(BSTNode root, int value)
    {
        if (root == null)
        {
            return root;
        }

        if (value < root.Value)
        {
            root.Left = DeleteRec(root.Left, value);
        }
        else if (value > root.Value)
        {
            root.Right = DeleteRec(root.Right, value);
        }
        else
        {
            if (root.Left == null)
            {
                return root.Right;
            }
            else if (root.Right == null)
            {
                return root.Left;
            }

            root.Value = MinValue(root.Right);
            root.Right = DeleteRec(root.Right, root.Value);
        }

        return root;
    }

    private int MinValue(BSTNode root)
    {
        int minValue = root.Value;
        while (root.Left != null)
        {
            minValue = root.Left.Value;
            root = root.Left;
        }
        return minValue;
    }

    public bool Search(int value)
    {
        return SearchRec(root, value);
    }

    private bool SearchRec(BSTNode root, int value)
    {
        if (root == null)
        {
            return false;
        }

        if (value == root.Value)
        {
            return true;
        }

        if (value < root.Value)
        {
            return SearchRec(root.Left, value);
        }
        else
        {
            return SearchRec(root.Right, value);
        }
    }

    public List<int> InOrderTraversal()
    {
        List<int> result = new List<int>();
        InOrderTraversalRec(root, result);
        return result;
    }

    private void InOrderTraversalRec(BSTNode root, List<int> result)
    {
        if (root != null)
        {
            InOrderTraversalRec(root.Left, result);
            result.Add(root.Value);
            InOrderTraversalRec(root.Right, result);
        }
    }

    public List<int> PreOrderTraversal()
    {
        List<int> result = new List<int>();
        PreOrderTraversalRec(root, result);
        return result;
    }

    private void PreOrderTraversalRec(BSTNode root, List<int> result)
    {
        if (root != null)
        {
            result.Add(root.Value);
            PreOrderTraversalRec(root.Left, result);
            PreOrderTraversalRec(root.Right, result);
        }
    }

    public List<int> PostOrderTraversal()
    {
        List<int> result = new List<int>();
        PostOrderTraversalRec(root, result);
        return result;
    }

    private void PostOrderTraversalRec(BSTNode root, List<int> result)
    {
        if (root != null)
        {
            PostOrderTraversalRec(root.Left, result);
            PostOrderTraversalRec(root.Right, result);
            result.Add(root.Value);
        }
    }
}
