### Solution:
```swift
public struct GraphQLResponse<DataType: GraphQL.AbstractResponse> {
    internal let data: DataType?
    internal let errors: [GraphQL.ResponseError]?

    public init(object: Any) throws {
        guard let rootDict = object as? [String: AnyObject] else {
            throw GraphQL.ViolationError(response: object)
        }

        do {
            let jsonData = try JSONSerialization.data(withJSONObject: object, options: [])
            let decoder = JSONDecoder()
            let parsedData = try decoder.decode(DataType.self, from: jsonData)
            self.data = parsedData
            self.errors = nil
        } catch {
            self.data = nil
            if let parsingError = error as? DecodingError {
                self.errors = [GraphQL.ResponseError.parsingError(parsingError)]
            } else {
                throw JsonParsingError(input: jsonData)
            }
        }
    }
}

func parseGraphQLResponse<DataType: GraphQL.AbstractResponse>(from object: Any) throws -> GraphQLResponse<DataType> {
    return try GraphQLResponse<DataType>(object: object)
}
```

In the solution, the `init` method of the `GraphQLResponse` struct uses `JSONSerialization` to convert the input `object` into JSON data. It then attempts to decode the JSON data into the specified `DataType` using `JSONDecoder`. If successful, it initializes the `data` property with the parsed data and sets `errors` to nil. If the decoding process encounters an error, it sets `data` to nil and populates the `errors` array with the appropriate error. If any errors occur during the parsing process, a `JsonParsingError` is thrown with the input data. The `parseGraphQLResponse` function simply calls the `init` method of `GraphQLResponse` and handles any potential errors.

