using System;

namespace CustomDataStructures
{
    public class BinarySearchTree
    {
        private class Node
        {
            public int Value;
            public Node Left;
            public Node Right;

            public Node(int value)
            {
                Value = value;
                Left = null;
                Right = null;
            }
        }

        private Node root;

        public void Insert(int value)
        {
            root = InsertRecursive(root, value);
        }

        private Node InsertRecursive(Node current, int value)
        {
            if (current == null)
            {
                return new Node(value);
            }

            if (value < current.Value)
            {
                current.Left = InsertRecursive(current.Left, value);
            }
            else if (value > current.Value)
            {
                current.Right = InsertRecursive(current.Right, value);
            }

            return current;
        }

        public void Delete(int value)
        {
            root = DeleteRecursive(root, value);
        }

        private Node DeleteRecursive(Node current, int value)
        {
            if (current == null)
            {
                return null;
            }

            if (value == current.Value)
            {
                if (current.Left == null)
                {
                    return current.Right;
                }
                else if (current.Right == null)
                {
                    return current.Left;
                }

                current.Value = FindMinValue(current.Right);
                current.Right = DeleteRecursive(current.Right, current.Value);
            }
            else if (value < current.Value)
            {
                current.Left = DeleteRecursive(current.Left, value);
            }
            else
            {
                current.Right = DeleteRecursive(current.Right, value);
            }

            return current;
        }

        private int FindMinValue(Node node)
        {
            return node.Left == null ? node.Value : FindMinValue(node.Left);
        }

        public bool Search(int value)
        {
            return SearchRecursive(root, value);
        }

        private bool SearchRecursive(Node current, int value)
        {
            if (current == null)
            {
                return false;
            }

            if (value == current.Value)
            {
                return true;
            }

            return value < current.Value ? SearchRecursive(current.Left, value) : SearchRecursive(current.Right, value);
        }

        public void InOrderTraversal()
        {
            InOrderTraversalRecursive(root);
            Console.WriteLine();
        }

        private void InOrderTraversalRecursive(Node current)
        {
            if (current != null)
            {
                InOrderTraversalRecursive(current.Left);
                Console.Write(current.Value + " ");
                InOrderTraversalRecursive(current.Right);
            }
        }

        public void PreOrderTraversal()
        {
            PreOrderTraversalRecursive(root);
            Console.WriteLine();
        }

        private void PreOrderTraversalRecursive(Node current)
        {
            if (current != null)
            {
                Console.Write(current.Value + " ");
                PreOrderTraversalRecursive(current.Left);
                PreOrderTraversalRecursive(current.Right);
            }
        }

        public void PostOrderTraversal()
        {
            PostOrderTraversalRecursive(root);
            Console.WriteLine();
        }

        private void PostOrderTraversalRecursive(Node current)
        {
            if (current != null)
            {
                PostOrderTraversalRecursive(current.Left);
                PostOrderTraversalRecursive(current.Right);
                Console.Write(current.Value + " ");
            }
        }
    }
}
