  int value;
  std::vector<TreePtr> children;

 public:
  KAryTree(int val) : value(val) {}

  void insert(int parentValue, int val) {
    TreePtr newNode = std::make_unique<KAryTree>(val);
    insertHelper(this, parentValue, std::move(newNode));
  }

  void insertHelper(KAryTree* node, int parentValue, TreePtr newNode) {
