class BinaryTreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

    def insert(self, value):
        if value < self.value:
            if self.left is None:
                self.left = BinaryTreeNode(value)
            else:
                self.left.insert(value)
        elif value > self.value:
            if self.right is None:
                self.right = BinaryTreeNode(value)
            else:
                self.right.insert(value)
        else:
            raise ValueError("Duplicate value not allowed in a binary search tree")

    def search(self, value):
        if value == self.value:
            return self
        elif value < self.value and self.left is not None:
            return self.left.search(value)
        elif value > self.value and self.right is not None:
            return self.right.search(value)
        else:
            return None

    def delete(self, value):
        if value == self.value:
            if self.left is None and self.right is None:
                return None  # Case 1: no children
            elif self.left is None:
                return self.right  # Case 2: only right child
            elif self.right is None:
                return self.left  # Case 2: only left child
            else:
                min_value = self.right.min_value()
                self.value = min_value
                self.right = self.right.delete(min_value)
                return self
        elif value < self.value and self.left is not None:
            self.left = self.left.delete(value)
        elif value > self.value and self.right is not None:
            self.right = self.right.delete(value)
        else:
            return None

    def traverse(self, order):
        if order == "inorder":
            if self.left is not None:
                left_result = self.left.traverse(order)
            else:
                left_result = []
            if self.right is not None:
                right_result = self.right.traverse(order)
            else:
                right_result = []
            return left_result + [self.value] + right_result
        elif order == "preorder":
            if self.left is not None:
                left_result = self.left.traverse(order)
            else:
                left_result = []
            if self.right is not None:
                right_result = self.right.traverse(order)
            else:
                right_result = []
            return [self.value] + left_result + right_result
        elif order == "postorder":
            if self.left is not None:
                left_result = self.left.traverse(order)
            else:
                left_result = []
            if self.right is not None:
                right_result = self.right.traverse(order)
            else:
                right_result = []
            return left_result + right_result + [self.value]
        else:
            raise ValueError("Invalid order. Expected 'inorder', 'preorder', or 'postorder'.")

    def is_valid(self):
        if self.left is None and self.right is None:
            return True
        elif self.left is not None and self.right is None:
            return self.left.is_valid() and self.left.value < self.value
        elif self.left is None and self.right is not None:
            return self.right.is_valid() and self.right.value > self.value
        else:
            return self.left.is_valid() and self.left.value < self.value and \
                self.right.is_valid() and self.right.value > self.value

    def min_value(self):
        if self.left is None:
            return self.value
        else:
            return self.left.min_value()

def create_binary_tree(values):
    root = BinaryTreeNode(values[0])
    for value in values[1:]:
        root.insert(value)
    return root
